/* nuá · RMRNM · portfolio interactions only. No booking API or personal data. */
(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const duration=n=>{const h=Math.floor(n/60),m=n%60;return [h?h+' ч':'',m?m+' мин':''].filter(Boolean).join(' ');};
const icon=name=>'<svg class="icon" aria-hidden="true"><use href="#'+name+'"/></svg>';
const extras={polish:{name:'Снятие покрытия',price:300,time:15},strength:{name:'Укрепление',price:400,time:20},design:{name:'Лёгкий дизайн',price:200,time:15},lashRemoval:{name:'Снятие прежних ресниц',price:400,time:20},brown:{name:'Коричневый эффект',price:300,time:0}};
const services={manicure:{name:'Маникюр без покрытия',label:'Выбрать маникюр без покрытия',category:'nails',price:1200,time:60,note:'Форма и аккуратный естественный вид',extras:['polish']},gel:{name:'Маникюр с гель-лаком',label:'Выбрать маникюр с гель-лаком',category:'nails',price:2400,time:105,note:'Ваш любимый оттенок или молочный нюд',extras:['polish','strength','design']},extensions:{name:'Наращивание ногтей',label:'Выбрать наращивание ногтей',category:'nails',price:3400,time:150,note:'Когда хочется другой длины и формы',extras:['polish','design']},classic:{name:'Классическое наращивание',label:'Выбрать классическое наращивание ресниц',category:'lashes',price:2800,time:120,note:'Естественная выразительность и аккуратная линия',extras:['lashRemoval','brown']},volume:{name:'Наращивание 2D',label:'Выбрать наращивание ресниц 2D',category:'lashes',price:3300,time:150,note:'Мягкий объём и более пушистый эффект',extras:['lashRemoval','brown']},removal:{name:'Снятие ресниц',label:'Выбрать снятие ресниц',category:'lashes',price:800,time:30,note:'Отдельная процедура снятия',extras:[]}};
const looks=[{id:'micro',type:'nails',image:'real-burgundy-french',ext:'jpg',name:'Бордовый френч',description:'Нюдовая база, квадратная форма и тонкая линия бордового цвета. Фотография предоставлена пользователем.',service:'gel'},{id:'cherry',type:'nails',image:'real-white-french',ext:'jpg',name:'Белый френч',description:'Чёткий белый край и полупрозрачная база на квадратных ногтях. Фотография предоставлена пользователем.',service:'gel'},{id:'pearl',type:'nails',image:'real-pink-nails',ext:'jpg',name:'Розовый акцент',description:'Ярко-розовое покрытие и прозрачные объёмные детали. Кадр приближен к маникюру без ретуши формы и цвета ногтей.',service:'gel'},{id:'gaze',type:'lashes',image:'lashes',name:'Выразительный взгляд',description:'Иллюстрация естественного эффекта ресниц. Конкретную длину и форму подбирают с мастером.',service:'classic'}];
let lookIndex=0,inspiration=null;
const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
const goVisit=()=>{$('#visit').scrollIntoView({behavior:motion()});$('#service').focus({preventScroll:true});};
const closeMenu=()=>{$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Открыть меню');$('#nav').classList.remove('open');};
$('.menu-button').addEventListener('click',()=>{const open=$('.menu-button').getAttribute('aria-expanded')!=='true';$('.menu-button').setAttribute('aria-expanded',String(open));$('.menu-button').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');$('#nav').classList.toggle('open',open);});
$$('#nav a').forEach(a=>a.addEventListener('click',closeMenu));
const renderServices=category=>{ $$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)));$('#service-list').innerHTML=Object.entries(services).filter(([,s])=>s.category===category).map(([key,s])=>'<article><div><h3>'+s.name+'</h3><p>'+s.note+' · '+duration(s.time)+'</p></div><strong>'+money(s.price)+'</strong><button type="button" data-service="'+key+'" aria-label="'+s.label+'">'+icon('diagonal')+'</button></article>').join('');};
$$('[data-category]').forEach(b=>b.addEventListener('click',()=>renderServices(b.dataset.category)));
const selectedExtras=()=>$$('#extras input:checked').map(el=>extras[el.value]).filter(Boolean);
const updateSummary=()=>{const s=services[$('#service').value],x=selectedExtras();$('#summary-service').textContent=s.name;$('#summary-price').textContent=money(s.price+x.reduce((n,e)=>n+e.price,0));$('#summary-duration').textContent=duration(s.time+x.reduce((n,e)=>n+e.time,0));$('#inspiration').hidden=!inspiration;$('#inspiration-text').textContent=inspiration?'Образ: '+inspiration.name:'';};
const renderExtras=()=>{const s=services[$('#service').value];if(inspiration&&inspiration.type!==s.category)inspiration=null;$('.extras-fieldset').hidden=!s.extras.length;$('#extras').innerHTML=s.extras.map(key=>{const e=extras[key];return '<label class="extra-option"><input type="checkbox" name="extra" value="'+key+'"><span>'+e.name+'</span><small>+ '+money(e.price)+(e.time?' · '+e.time+' мин':'')+'</small></label>';}).join('');updateSummary();};
$('#service').addEventListener('change',renderExtras);$('#extras').addEventListener('change',updateSummary);
$('#clear-inspiration').addEventListener('click',()=>{inspiration=null;updateSummary();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-service]');if(b&&services[b.dataset.service]){$('#service').value=b.dataset.service;renderExtras();goVisit();}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const filter=b.dataset.filter;$$('[data-filter]').forEach(button=>button.setAttribute('aria-pressed',String(button===b)));$$('.look').forEach(el=>el.hidden=filter!=='all'&&el.dataset.type!==filter);$('.look-grid').classList.toggle('single',$$('.look').filter(el=>!el.hidden).length===1);}));
const showLook=index=>{lookIndex=(index+looks.length)%looks.length;const l=looks[lookIndex];$('#look-image').src='assets/'+l.image+'.'+(l.ext||'webp');$('#look-image').alt=l.name+(l.ext?' — фото пользователя':' — иллюстрация RMRNM');$('#look-dialog').dataset.activeLook=l.id;$('#look-credit').textContent=l.ext?'Фото пользователя · Портфолио RMRNM':'Иллюстрация RMRNM · ImageGen';$('#look-title').textContent=l.name;$('#look-description').textContent=l.description;$('#look-counter').textContent=(lookIndex+1)+' / '+looks.length;};
$$('[data-look]').forEach(b=>b.addEventListener('click',()=>{showLook(looks.findIndex(l=>l.id===b.dataset.look));$('#look-dialog').showModal();}));
$('#look-prev').addEventListener('click',()=>showLook(lookIndex-1));$('#look-next').addEventListener('click',()=>showLook(lookIndex+1));
$('#choose-look').addEventListener('click',()=>{const l=looks[lookIndex];inspiration=l;$('#service').value=l.service;renderExtras();$('#look-dialog').close();goVisit();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if($('#look-dialog').open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showLook(lookIndex+(e.key==='ArrowRight'?1:-1));}});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));
const date=$('#visit-date');
const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
const today=[parts.year,parts.month,parts.day].join('-');date.min=today;date.value=today;date.max=new Date(Date.parse(today+'T12:00:00Z')+60*86400000).toISOString().slice(0,10);
$('#visit-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const s=services[$('#service').value],x=selectedExtras(),price=s.price+x.reduce((n,e)=>n+e.price,0),time=s.time+x.reduce((n,e)=>n+e.time,0),data=new FormData(e.target);const when=new Date(String(data.get('date'))+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'long',timeZone:'Europe/Moscow'});const entries=[['Процедура',s.name],['Желаемая дата',when],['Пример времени',String(data.get('time'))],['Длительность',duration(time)]];$('#plan-content').innerHTML='<dl>'+entries.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+(x.length?'<p>Дополнения: '+x.map(v=>esc(v.name)).join(', ')+'.</p>':'')+(inspiration?'<p>Вдохновение: '+esc(inspiration.name)+'.</p>':'')+'<p class="plan-total">'+money(price)+'</p>';$('#plan-dialog').showModal();});
$('#project-info-open').addEventListener('click',()=>$('#project-info').showModal());
renderExtras();
})();
